<template><view class="page"><view class="back" @tap="back">‹</view><view class="head"><text class="title">账号设置</text></view><view class="card settings"><view class="setting-row" @tap="changeAvatar"><text>头像</text><view class="row-value"><image v-if="avatar" class="avatar" :src="avatar" mode="aspectFill" /><view v-else class="avatar">绿</view><text>›</text></view></view><view class="setting-row" @tap="changeName"><text>用户名</text><view class="row-value"><text class="muted">{{name}}</text><text>›</text></view></view><view class="setting-row" @tap="changePassword"><text>密码</text><view class="row-value"><text class="muted">修改登录密码</text><text>›</text></view></view></view></view></template>
<script>export default{data(){return{avatar:uni.getStorageSync('enterprise_avatar')||'',name:uni.getStorageSync('enterprise_name')||'绿色生活品牌'}},methods:{back(){uni.navigateBack()},changeAvatar(){uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:res=>{this.avatar=res.tempFilePaths[0];uni.setStorageSync('enterprise_avatar',this.avatar)}})},changeName(){uni.showModal({title:'修改用户名',editable:true,placeholderText:this.name,success:res=>{if(res.confirm&&res.content){this.name=res.content;uni.setStorageSync('enterprise_name',res.content);uni.showToast({title:'用户名已保存',icon:'success'})}}})},changePassword(){uni.showModal({title:'修改密码',editable:true,placeholderText:'请输入新密码',success:res=>{if(res.confirm&&res.content){uni.setStorageSync('enterprise_password',res.content);uni.showToast({title:'密码已更新',icon:'success'})}}})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.back{display:flex;align-items:center;width:68rpx;height:68rpx;font-size:58rpx}.settings-page{padding-top:18rpx}.settings-page .head{padding:40rpx 4rpx}.settings{padding:0;overflow:hidden}.setting-row{display:flex;align-items:center;justify-content:space-between;min-height:112rpx;padding:0 28rpx;border-bottom:1rpx solid #edf1ef;color:#53615f;font-size:28rpx}.setting-row:last-child{border:0}.row-value{display:flex;align-items:center;gap:14rpx}.avatar{display:flex;align-items:center;justify-content:center;width:72rpx;height:72rpx;border-radius:50%;background:#d6e6e3;color:#006d37;font-size:28rpx}</style>
